PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Azure Well-Architected assessment</title>
<style>
:root{--bg:#0b1220;--p:#111a2e;--p2:#16213a;--line:#24324f;--t:#e7ecf6;--m:#8fa0c0;--a:#4da3ff;--g:#34d399;--r:#f87171;--y:#fbbf24}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font:14px/1.45 Segoe UI,system-ui,sans-serif}.wrap{max-width:1350px;margin:0 auto;padding:18px}a{color:var(--a)}
.hero{background:linear-gradient(120deg,#0f2a52,#13203b);border:1px solid var(--line);border-radius:14px;padding:18px 22px}.hero h1{margin:0;font-size:22px}.hero p{margin:4px 0 0;color:var(--m)}
.card{background:var(--p);border:1px solid var(--line);border-radius:12px;padding:14px;margin:14px 0}.card h2{margin:0 0 10px;font-size:15px}
label{display:block;color:var(--m);font-size:12.5px;margin:8px 0 3px}select,input{width:100%;background:var(--p2);border:1px solid var(--line);color:var(--t);border-radius:8px;padding:7px 10px}
.g{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}.btn{background:var(--a);color:#06101f;border:0;border-radius:8px;padding:8px 14px;font-weight:600;cursor:pointer;margin-top:10px}.btn.s{background:var(--p2);color:var(--t);border:1px solid var(--line)}.btn:disabled{opacity:.5}
table{border-collapse:collapse;width:100%}th,td{padding:6px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--m)}.scr{overflow:auto;max-height:560px}
.note{color:var(--m);font-size:12.5px}.subs{max-height:230px;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:6px 10px;background:var(--p2)}.subs label{display:flex;gap:8px;align-items:center;margin:4px 0;color:var(--t);font-size:13px}.subs input{width:auto}
.pil{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.pc{background:var(--p2);border:1px solid var(--line);border-radius:12px;padding:12px;cursor:pointer}.pc.sel{border-color:var(--a)}.pc .n{font-size:30px;font-weight:700}.pc .r{font-size:12px}
.good{color:var(--g)}.fair{color:var(--y)}.bad{color:var(--r)}.sv{display:inline-block;border-radius:99px;padding:1px 9px;font-size:12px;font-weight:600}.sv.High{background:#4a1d1d;color:#fca5a5}.sv.Medium{background:#4a3a0b;color:#fbd56a}.sv.Low{background:#1f2d4a;color:#9db8e8}
.kpi{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.kpi div{background:var(--p2);border:1px solid var(--line);border-radius:10px;padding:10px}.kpi b{display:block;font-size:19px}
details{border-bottom:1px solid var(--line);padding:6px 0}summary{cursor:pointer}.bar{height:8px;border-radius:4px;background:var(--line);overflow:hidden}.bar i{display:block;height:100%}
</style></head><body><div class="wrap">__CGNAV__
<div class="hero"><h1>Azure Well-Architected assessment</h1><p>Sign in to the customer directory, tick the subscriptions, and run. It reads every resource, 30 days of real usage metrics, cost, Defender, backup and policy, and reports against all five Well-Architected pillars: cost optimisation, reliability, security, operational excellence and performance efficiency. Read-only.</p></div>
<div class="card"><h2>1 · Customer directory</h2><div class="g">
<div><label>Directory (tenant)</label><select id="tsel"><option value="">Loading directories...</option></select><input id="tenant" placeholder="or paste a tenant ID" style="margin-top:6px"></div>
<div><label>Customer name (for the report)</label><input id="cust" placeholder="filled from the directory"></div></div>
<div class="note" id="msg"></div></div>
<div class="card"><h2>2 · Subscriptions <span class="note">tick the ones to assess</span></h2>
<div style="margin-bottom:6px"><button class="btn s" id="all" style="margin:0 6px 0 0">Tick all</button><button class="btn s" id="none" style="margin:0">Clear</button></div>
<div class="subs" id="subs"><span class="note">Choose a directory first.</span></div>
</div>
<div class="card"><h2>3 · Assessment modules <span class="note">run any combination; each is independent</span></h2><div class="subs" id="mods" style="max-height:none"></div>
<button class="btn s" id="verify" disabled>Verify access first</button> <span class="note" id="vmsg"></span><div id="vres"></div>
<button class="btn" id="run" disabled>4 · Run assessment on ticked subscriptions</button> <span class="note" id="rmsg"></span></div>
<div id="res"></div>
<div class="card"><h2>Previous assessments</h2><div id="hist" class="scr"></div></div></div>
<script>
var $=function(i){return document.getElementById(i)};function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function j(u,o){return fetch(u,o).then(function(r){return r.json()})}
function post(u,b){return j(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)})}
var MODS=[['finops','FinOps & Cost Optimization','spend, idle resources, rightsizing from 30-day usage, licence and commitment savings'],['infra','Azure Infrastructure & Landing Zone','inventory, subscriptions, policy, hub-and-spoke, DNS, private endpoints, lifecycle'],['security','Cloud Security','Defender findings, public exposure, RBAC, encryption, patching'],['waf','WAF & Network Security','WAF coverage map, Detection vs Prevention mode, direct exposure, firewall policy'],['modern','Application & Database Modernization','VM to App Service / containers / managed SQL candidates'],['backup','Backup, DR & Resilience','backup coverage, zones, redundancy, retired SKUs'],['perfops','Performance & Operations','CPU/memory pressure, scaling, monitoring coverage']];
$('mods').innerHTML=MODS.map(function(m){return '<label><input type="checkbox" value="'+m[0]+'" checked> <b>'+m[1]+'</b> <span class="note">'+m[2]+'</span></label>'}).join('');
function modsList(){return [].slice.call($('mods').querySelectorAll('input:checked')).map(function(x){return x.value})}
var PIL=['Cost Optimization','Reliability','Security','Operational Excellence','Performance Efficiency'],R=null,SEL=PIL[0];
function money(n){return Math.round(n||0).toLocaleString()}
j('/ai/waf/tenants').then(function(d){$('tsel').innerHTML='<option value="">Select a directory</option>'+(d.tenants||[]).map(function(t){return '<option value="'+t.id+'" data-n="'+esc(t.name)+'">'+esc(t.name)+(t.domain?' ('+esc(t.domain)+')':'')+'</option>'}).join('');if(d.error)$('tsel').innerHTML='<option value="">'+esc(d.error)+'</option>'});
$('tsel').onchange=function(){$('tenant').value=this.value;var o=this.selectedOptions[0];if(o&&o.dataset.n)$('cust').value=o.dataset.n;if(this.value)loadSubs()};
$('tenant').onchange=function(){if(this.value.trim())loadSubs()};
function subsList(){return [].slice.call($('subs').querySelectorAll('input:checked')).map(function(x){return x.value})}
function upd(){$('run').disabled=!subsList().length;$('verify').disabled=!subsList().length}
$('mods').onchange=function(){if(!modsList().length)[].forEach.call($('mods').querySelectorAll('input'),function(x){x.checked=true})};
$('verify').onclick=function(){$('vmsg').textContent='Checking access...';$('vres').innerHTML='';post('/ai/waf/verify',{tenant:$('tenant').value.trim(),subscriptions:subsList()}).then(function(d){if(d.error){$('vmsg').textContent=d.error;return}$('vmsg').textContent='';$('vres').innerHTML='<table><tr><th>Evidence source</th><th>Access</th><th>Role needed</th></tr>'+d.checks.map(function(c){return '<tr><td>'+esc(c.source)+'</td><td class="'+(c.ok?'good':'bad')+'">'+(c.ok?'Readable':'Not readable: '+esc(c.detail))+'</td><td>'+esc(c.role)+'</td></tr>'}).join('')+'</table><div class="note">Anything not readable is listed in the report under what still needs evidence. The assessment still runs on the rest.</div>'})};
function loadSubs(){$('msg').textContent='Loading subscriptions...';$('subs').innerHTML='';j('/ai/waf/subs?tenant='+encodeURIComponent($('tenant').value.trim())).then(function(d){
 if(d.error&&/token for that directory|sign-in has expired/i.test(d.error)){needSignin();return}
 $('msg').textContent=d.error||'';var s=d.subscriptions||[];
 $('subs').innerHTML=s.map(function(x){return '<label><input type="checkbox" value="'+x.id+'"'+(x.state==='Enabled'?' checked':'')+'> '+esc(x.name)+' <span class="note">'+x.id.slice(0,8)+' · '+esc(x.state)+'</span></label>'}).join('')||'<span class="note">No subscriptions visible in this directory for your account.</span>';
 $('subs').onchange=upd;upd()})}
function needSignin(){var m=$('msg');m.innerHTML='You are not signed in to this directory yet. <button class="btn s" id="sgn" style="margin:0 6px">Sign in to this directory</button>';
 $('sgn').onclick=function(){m.textContent='Starting sign-in...';post('/ai/boq/signin',{tenant:$('tenant').value.trim()}).then(function(d){
  if(d.error){m.textContent=d.error;return}
  window.open(d.url,'_blank','noopener');
  m.innerHTML='Open <a href="'+esc(d.url)+'" target="_blank" rel="noopener">'+esc(d.url)+'</a> and enter code <b>'+esc(d.code)+'</b>, then sign in with your account for this customer. Waiting...';
  var n=0,t=setInterval(function(){n++;if(n>120){clearInterval(t);m.textContent='Timed out. Pick the directory again.';return}
   post('/ai/boq/signinpoll',{fid:d.fid}).then(function(s){if(s.status==='done'){clearInterval(t);loadSubs()}else if(s.status==='failed'||s.status==='denied'){clearInterval(t);m.textContent=s.message||'Sign-in failed.'}})},3000)})}}
$('all').onclick=function(){[].forEach.call($('subs').querySelectorAll('input'),function(x){x.checked=true});upd()};
$('none').onclick=function(){[].forEach.call($('subs').querySelectorAll('input'),function(x){x.checked=false});upd()};
$('run').onclick=function(){var s=subsList();if(!s.length)return;$('run').disabled=true;$('rmsg').textContent='Starting...';post('/ai/waf/start',{tenant:$('tenant').value.trim(),subscriptions:s,customer:$('cust').value.trim(),modules:modsList()}).then(function(d){
 if(d.error){$('rmsg').textContent=d.error;$('run').disabled=false;return}poll(d.task,0)})};
function poll(id,n){j('/ai/waf/state?id='+id).then(function(s){
 if(s.status==='done'){$('rmsg').textContent='Done.';$('run').disabled=false;show(s.id);hist();return}
 if(s.status==='failed'||s.status==='unknown'){$('rmsg').textContent=s.error||'The assessment stopped. Try again.';$('run').disabled=false;return}
 $('rmsg').textContent=(s.msg||'Working...');if(n<900)setTimeout(function(){poll(id,n+1)},3000)})}
function show(id){j('/ai/waf/result?id='+id).then(function(r){R=r;SEL=PIL[0];draw()})}
function draw(){var r=R.result,s=r.summary,h='';
 h+='<div class="card"><h2>'+esc(R.customer||R.tenant)+' · assessed '+esc(R.time.replace('T',' '))+' UTC</h2><div class="kpi"><div><b>'+s.resources+'</b>resources in '+s.subscriptions+' subscription(s)</div><div><b>'+s.currency+' '+money(s.cost_30d)+'</b>spend, last 30 days</div><div><b class="good">'+s.currency+' '+money(s.estimated_saving_30d)+'</b>estimated saving / month</div><div><b>'+s.findings+'</b>findings ('+s.high+' high)</div><div><b>'+s.metrics_read+'/'+s.metrics_planned+'</b>resources with usage metrics</div></div>';
 h+='<p style="margin:12px 0 4px">'+esc(r.executive_summary||'')+'</p><a class="btn" href="/ai/waf/pdf?id='+R.id+'" style="text-decoration:none;display:inline-block">Download PDF report</a> <a class="btn s" href="/ai/waf/xlsx?id='+R.id+'" style="text-decoration:none;display:inline-block">Download Excel (all affected resources)</a></div>';
 h+='<div class="pil">'+PIL.map(function(p){var v=r.scores[p],c=v.rating==='Good'?'good':(v.rating==='Fair'?'fair':'bad');return '<div class="pc'+(p===SEL?' sel':'')+'" data-p="'+p+'"><div class="note">'+p+'</div><div class="n '+c+'">'+v.score+'</div><div class="r '+c+'">'+v.rating+' · '+v.findings+' findings'+(v.high?', '+v.high+' high':'')+'</div><div class="bar"><i style="width:'+v.score+'%;background:var(--'+(c==='good'?'g':(c==='fair'?'y':'r'))+')"></i></div></div>'}).join('')+'</div>';
 h+='<div class="card"><h2>Highest-value actions</h2><table><tr><th>#</th><th>Module</th><th>Action</th><th>Sev.</th><th>Affected</th><th>Est. '+s.currency+'/month</th><th>What to do</th></tr>'+(r.top_actions||[]).map(function(a,i){return '<tr><td>'+(i+1)+'</td><td>'+esc(a.module)+'</td><td>'+esc(a.title)+'</td><td><span class="sv '+a.severity+'">'+a.severity+'</span></td><td>'+a.count+'</td><td>'+(a.saving?money(a.saving):'')+'</td><td>'+esc(a.recommendation)+'</td></tr>'}).join('')+'</table>'+(s.gross_saving_30d>s.estimated_saving_30d?'<div class="note">Savings are counted once per resource: gross of all findings '+s.currency+' '+money(s.gross_saving_30d)+', net after overlaps '+s.currency+' '+money(s.estimated_saving_30d)+'.</div>':'')+'</div>';
 var fl=r.findings.filter(function(f){return f.pillar===SEL});
 h+='<div class="card"><h2>'+SEL+'</h2>'+(fl.length?fl.map(function(f){return '<details><summary><span class="sv '+f.severity+'">'+f.severity+'</span> <b>'+esc(f.title)+'</b> <span class="note">· '+f.count+(f.population?' of '+f.population:'')+' affected · '+esc(f.area)+(f.saving?' · est. saving '+s.currency+' '+money(f.saving)+' / month':'')+'</span></summary><div class="note" style="margin:6px 0"><b>What to do:</b> '+esc(f.recommendation)+(f.basis?'<br>'+esc(f.basis):'')+'</div><table><tr><th>Resource</th><th>Type</th><th>Resource group</th><th>Detail</th></tr>'+f.items.slice(0,25).map(function(i){return '<tr><td>'+esc(i.name)+'</td><td>'+esc(i.type)+'</td><td>'+esc(i.rg)+'</td><td>'+esc(i.detail)+'</td></tr>'}).join('')+'</table>'+(f.count>25?'<div class="note">+ '+(f.count-25)+' more in the Excel file.</div>':'')+'</details>'}).join(''):'<div class="note">No findings from the checks that could be run.</div>')+'</div>';
 h+='<div class="card"><h2>Utilisation and right-sizing (30 days)</h2><div class="scr"><table><tr><th>Resource</th><th>Size / tier</th><th>State</th><th>CPU avg %</th><th>CPU peak %</th><th>Memory used %</th><th>Cost 30d</th><th>Verdict</th><th>Suggested</th></tr>'+r.utilization.filter(function(u){return u.verdict!=='No metrics'}).slice(0,150).map(function(u){var c=u.verdict==='Scale down'?'fair':(u.verdict==='Scale up / out'?'bad':'');return '<tr><td>'+esc(u.name)+'</td><td>'+esc(u.size)+'</td><td>'+esc(u.power)+'</td><td>'+(u.cpu_avg==null?'':u.cpu_avg)+'</td><td>'+(u.cpu_max==null?'':u.cpu_max)+'</td><td>'+(u.mem_used_avg==null?'':u.mem_used_avg)+'</td><td>'+u.cost_30d+'</td><td class="'+c+'">'+esc(u.verdict)+'</td><td>'+esc(u.target)+'</td></tr>'}).join('')+'</table></div></div>';
 h+='<div class="card"><h2>Landing zone and network design</h2><table><tr><th>Check</th><th>Result</th><th>Evidence</th><th>What to do</th></tr>'+r.landing_zone.map(function(l){return '<tr><td>'+esc(l.check)+'</td><td class="'+(l.ok?'good':'bad')+'">'+(l.ok?'In place':'Gap')+'</td><td>'+esc(l.evidence)+'</td><td>'+(l.ok?'':esc(l.fix))+'</td></tr>'}).join('')+'</table></div>';
 if(r.modernization&&r.modernization.length)h+='<div class="card"><h2>Modernisation candidates</h2><table><tr><th>Workload type</th><th>VMs</th><th>Option</th><th>Examples</th></tr>'+r.modernization.map(function(m){return '<tr><td>'+esc(m.category)+'</td><td>'+m.count+'</td><td>'+esc(m.advice)+'</td><td>'+esc(m.examples.join(', '))+'</td></tr>'}).join('')+'</table></div>';
 if(r.waf_map&&r.waf_map.length)h+='<div class="card"><h2>WAF coverage map (web apps)</h2><div class="scr"><table><tr><th>App</th><th>Hostname</th><th>Public</th><th>Front end</th></tr>'+r.waf_map.slice(0,200).map(function(w){return '<tr><td>'+esc(w.app)+'</td><td>'+esc(w.host)+'</td><td>'+(w.public?'yes':'no')+'</td><td class="'+(w.front==='None'?'bad':'')+'">'+esc(w.front)+'</td></tr>'}).join('')+'</table></div></div>';
 h+='<div class="card"><h2>What was verified, and what still needs evidence</h2><table><tr><th>Evidence source</th><th>Status</th><th>Role needed</th></tr>'+(r.verified||[]).map(function(v){return '<tr><td>'+esc(v.source)+'</td><td class="'+(v.status==='ok'?'good':(v.status==='failed'?'bad':''))+'">'+({ok:'Read',failed:'Could not read',skipped:'Not requested'}[v.status]||v.status)+'</td><td>'+esc(v.role)+'</td></tr>'}).join('')+'</table>'+(r.needs_evidence||[]).map(function(n){return '<div class="note">• '+esc(n.item)+' <i>('+esc(n.module)+')</i></div>'}).join('')+'</div>';
 if(r.warnings&&r.warnings.length)h+='<div class="card"><h2>Could not be read</h2>'+r.warnings.map(function(w){return '<div class="note">• '+esc(w)+'</div>'}).join('')+'</div>';
 $('res').innerHTML=h;[].forEach.call($('res').querySelectorAll('.pc'),function(e){e.onclick=function(){SEL=e.dataset.p;draw()}})}
function hist(){j('/ai/waf/history').then(function(d){var h=d.history||[];$('hist').innerHTML=h.length?'<table><tr><th>When (UTC)</th><th>Customer</th><th>Subs</th><th>Scores (cost / rel / sec / ops / perf)</th><th>Findings</th><th>Est. saving</th><th></th></tr>'+h.map(function(x){var s=x.scores||{};return '<tr><td>'+esc(x.time.replace('T',' '))+'</td><td>'+esc(x.customer||x.tenant)+'</td><td>'+x.subscriptions+'</td><td>'+PIL.map(function(p){return s[p]}).join(' / ')+'</td><td>'+x.findings+'</td><td>'+money(x.saving)+'</td><td><a href="#" data-i="'+x.id+'">Open</a> · <a href="/ai/waf/pdf?id='+x.id+'">PDF</a></td></tr>'}).join('')+'</table>':'<div class="note">None yet.</div>';
 [].forEach.call($('hist').querySelectorAll('a[data-i]'),function(a){a.onclick=function(e){e.preventDefault();show(a.dataset.i);window.scrollTo(0,0)}})})}
hist();
</script></body></html>"""
